sys_trigger.script:
// SN Assignment Rule Auditor — Nightly Health Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function() {
    try {
        var engine = new AssignmentRuleEngine();
        var result = engine.scanAll(null);
        gs.info('AssignmentRuleAuditor: Nightly scan complete. ' +
                'Tables scanned: ' + Object.keys(result.tables).length +
                ', Conflicts: ' + Object.values(result.tables).reduce(function(s, t) { return s + t.conflicts; }, 0) +
                ', Dead rules: ' + Object.values(result.tables).reduce(function(s, t) { return s + t.dead_rules; }, 0) +
                ', Stale conditions: ' + Object.values(result.tables).reduce(function(s, t) { return s + t.stale_conditions; }, 0));
    } catch (e) {
        gs.error('AssignmentRuleAuditor: Nightly scan failed: ' + e.message);
    }
})();

// SN Assignment Rule Auditor — Weekly Baseline Snapshot
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function() {
    try {
        var helper = new AssignmentRuleHelper();
        var weekLabel = 'Baseline ' + new GlideDateTime().getDate().getValue();
        var baselineId = helper.createBaseline(weekLabel, null);
        if (baselineId) {
            gs.info('AssignmentRuleAuditor: Weekly baseline created: ' + baselineId);
        } else {
            gs.warn('AssignmentRuleAuditor: Weekly baseline creation failed');
        }
    } catch (e) {
        gs.error('AssignmentRuleAuditor: Weekly baseline failed: ' + e.message);
    }
})();

// SN Assignment Rule Auditor — Cleanup Old Scan Results
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function() {
    try {
        var helper = new AssignmentRuleHelper();
        var deleted = helper.purgeOldResults(90);
        gs.info('AssignmentRuleAuditor: Cleanup complete. Deleted ' + deleted + ' old scan results.');
    } catch (e) {
        gs.error('AssignmentRuleAuditor: Cleanup failed: ' + e.message);
    }
})();

sys_script.script:
// SN Assignment Rule Auditor — Auto-set scanned_at on insert
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function executeRule(current, previous /*null when async*/) {
    if (!current.scanned_at) {
        current.scanned_at = new GlideDateTime();
    }
})(current, previous);

// SN Assignment Rule Auditor — Auto-set created_at on insert
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function executeRule(current, previous /*null when async*/) {
    if (!current.created_at) {
        current.created_at = new GlideDateTime();
    }
})(current, previous);
